head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00400_01.xml";
scwin.vKisCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 조회조건 기업코드

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_AudtOpinSpeclablContn.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    if (scwin.vKisCd == "") {
        return false;
    }
    return true;
};


/**
 * 감사의견 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_AudtOpinSpeclablContn);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.audtOpinSpeclablContnAE" + "&outputMessageId=FIS_AUDT_OPIN_SPECLABL_CONTN" + "&param01=" + scwin.vKisCd;
    dts_AudtOpinSpeclablContn.DataID = encodeURI(url);
    dts_AudtOpinSpeclablContn.Reset();
};


/**
 * 감사의견 팝업
 */
scwin.fn_AudtOpinSrchOpen = async function(pRow) {
    // 적정인경우 스킵
    if (dts_AudtOpinSpeclablContn.getCellData(pRow, "AUDT_OPIN_CD") == "10") {
        // return;

    }
    fn_GetPar = fn_GetParKey;
    await $c.frame.CreateDialogFrame("AUDT_OPIN", "./ULDFIS00300_P1.gfm", "감사의견 검색", 100, 100, 540 + 20, 250 + 125, "window");
};


/**
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKey = function(arrPar) {
    var nRow = dts_AudtOpinSpeclablContn.getRowPosition();
    arrPar[0] = dts_AudtOpinSpeclablContn.getCellData(nRow, "COM_CD");
    arrPar[1] = dts_AudtOpinSpeclablContn.getCellData(nRow, "BAS_YYMM");
    arrPar[2] = "krx.lds.stf.fis.select.audtOpinAE";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_AudtOpinSpeclablContn.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_AudtOpinSpeclablContn, "감사의견", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_AudtOpinSpeclablContn_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_AudtOpinSpeclablContn);
    $c.stf.alert_error(dts_AudtOpinSpeclablContn);
};
scwin.dts_AudtOpinSpeclablContn_OnLoadCompleted = function(rowcount) {
    if (dts_AudtOpinSpeclablContn.errorMsg) {
        $c.win.alert(dts_AudtOpinSpeclablContn.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_AudtOpinSpeclablContn);
};
scwin.grd_AudtOpinSpeclablContn_OnDblClick = function(row, colid) {
    if (colid == "AUDT_OPIN_NM") {
        if (dts_AudtOpinSpeclablContn.getCellData(dts_AudtOpinSpeclablContn.getRowPosition(), "CTNT") == "1") {
            // 감사의견  팝업 오픈
            scwin.fn_AudtOpinSrchOpen(row);
        }
    }
};
